create table if not exists public.user_blocks (blocker_id uuid not null references auth.users(id) on delete cascade,blocked_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),constraint user_blocks_not_self check(blocker_id<>blocked_id));
create table if not exists public.content_reports (id uuid primary key default gen_random_uuid(),reporter_user_id uuid not null references auth.users(id) on delete cascade,target_type text not null check(target_type in ('post','user','comment','entity')),target_id uuid not null,reason text not null check(reason in ('spam','harassment','hate','violence','nudity','scam','misinformation','other')),details text not null default '',status text not null default 'pending' check(status in ('pending','reviewing','actioned','dismissed')),moderator_user_id uuid references auth.users(id),moderator_note text not null default '',created_at timestamptz not null default now(),reviewed_at timestamptz);
create index if not exists content_reports_status_created_idx on public.content_reports(status,created_at);create index if not exists content_reports_target_idx on public.content_reports(target_type,target_id);
alter table public.user_blocks enable row level security;alter table public.content_reports enable row level security;revoke all on public.user_blocks,public.content_reports from anon,authenticated;grant select on public.user_blocks,public.content_reports to authenticated;
create policy user_blocks_participant_read on public.user_blocks for select to authenticated using(blocker_id=(select auth.uid()) or blocked_id=(select auth.uid()));
create policy content_reports_reporter_read on public.content_reports for select to authenticated using(reporter_user_id=(select auth.uid()));
create or replace function public.block_user(p_blocked_user_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if auth.uid() is null then raise exception 'Sign in required';end if;if p_blocked_user_id is null or p_blocked_user_id=auth.uid() then raise exception 'Invalid account';end if;if not exists(select 1 from public.user_profiles where id=p_blocked_user_id) then raise exception 'Account not found';end if;insert into public.user_blocks(blocker_id,blocked_id) values(auth.uid(),p_blocked_user_id) on conflict do nothing;delete from public.user_follows where (follower_id=auth.uid() and following_id=p_blocked_user_id) or (follower_id=p_blocked_user_id and following_id=auth.uid());end $$;
revoke all on function public.block_user(uuid) from public,anon;grant execute on function public.block_user(uuid) to authenticated;
create or replace function public.unblock_user(p_blocked_user_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if auth.uid() is null then raise exception 'Sign in required';end if;delete from public.user_blocks where blocker_id=auth.uid() and blocked_id=p_blocked_user_id;end $$;
revoke all on function public.unblock_user(uuid) from public,anon;grant execute on function public.unblock_user(uuid) to authenticated;
create or replace function public.report_content(p_target_type text,p_target_id uuid,p_reason text,p_details text default '') returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare v_exists boolean;v_owner uuid;v_id uuid;
begin if auth.uid() is null then raise exception 'Sign in required';end if;if p_target_type not in ('post','user','comment','entity') then raise exception 'Invalid report target';end if;if p_reason not in ('spam','harassment','hate','violence','nudity','scam','misinformation','other') then raise exception 'Invalid report reason';end if;
if p_target_type='post' then select exists(select 1 from public.user_posts where id=p_target_id),max(user_id) into v_exists,v_owner from public.user_posts where id=p_target_id;
elsif p_target_type='user' then v_exists:=exists(select 1 from public.user_profiles where id=p_target_id);v_owner:=p_target_id;
elsif p_target_type='comment' then select exists(select 1 from public.post_comments where id=p_target_id),max(user_id) into v_exists,v_owner from public.post_comments where id=p_target_id;
else select exists(select 1 from public.directory_entities where id=p_target_id),max(created_by) into v_exists,v_owner from public.directory_entities where id=p_target_id;end if;
if not v_exists then raise exception 'Content not found';end if;if v_owner=auth.uid() then raise exception 'You cannot report your own content';end if;
if exists(select 1 from public.content_reports where reporter_user_id=auth.uid() and target_type=p_target_type and target_id=p_target_id and status in ('pending','reviewing')) then raise exception 'You already reported this content';end if;
insert into public.content_reports(reporter_user_id,target_type,target_id,reason,details) values(auth.uid(),p_target_type,p_target_id,p_reason,left(trim(coalesce(p_details,'')),2000)) returning id into v_id;return v_id;end $$;
revoke all on function public.report_content(text,uuid,text,text) from public,anon;grant execute on function public.report_content(text,uuid,text,text) to authenticated;